from collections import deque

def solve():
    n = int(input())
    a = list(map(int, input().split()))
    p = list(map(int, input().split()))
    v = list(map(int, input().split()))

    adj = [[] for _ in range(n + 1)]
    for i in range(n):
        adj[a[i]].append(i + 1)

    wins = [0] * n
    visited = [False] * (n + 1)
    q = deque()

    for i in range(1, n + 1):
        if not visited[i]:
            cycle = []
            while not visited[i]:
                visited[i] = True
                cycle.append(i)
                i = a[i - 1]
            if cycle:
                q.append(cycle)

    while q:
        cycle = q.popleft()
        m = len(cycle)
        for i in range(m):
            elf = cycle[i] - 1
            dwarf = cycle[(i + 1) % m] - 1
            if v[elf] > p[dwarf]:
                wins[elf] += 1
            else:
                wins[elf] += 0
            for next_elf in adj[cycle[i]]:
                if next_elf - 1 not in cycle:
                    cycle.append(next_elf)
        if len(cycle) > m:
            q.append(cycle[m:])

    print(sum(wins))

solve()
